before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <vector>
int main() {
    std::vector<int> a{2, 4};
    auto b = a;
    b[0] = 9;
    std::cout << a[0] << ' ' << b[0] << '\n';
}

```

after:
Follow the copy, then the change to its first item. Both vectors have a valid item at index zero.

```cpp
#include <iostream>
#include <vector>
int main() {
    std::vector<int> a{2, 4};
    auto b = a;
    b[0] = 9;
    std::cout << a[0] << ' ' << b[0] << '\n';
}

```
